/**
 * This is the qualitative causal reasoning test
 * 
 * The qualitative causal reasoning evaluation category tests whether causal loop diagrams (CLDs) 
 * generated by LLMs include key variables and causal mechanisms that domain experts consider essential 
 * for understanding a particular system. Unlike quantitative models that focus on stocks and flows, 
 * this category evaluates whether qualitative models capture the important conceptual elements 
 * and causal relationships that experts have identified as critical to understanding system behavior.
 *
 * The evaluation works by providing the LLM with expert knowledge about a domain, then checking 
 * whether the generated CLD includes specific variables, concepts, and causal relationships 
 * that experts have identified as important for representing the system. This allows us 
 * to assess whether the model captures the essential qualitative understanding that makes 
 * it useful for policy analysis and systems thinking.
 * 
 * @module categories/qualitativeCausalReasoning
 */

import utils from '../../utilities/utils.js';
import { validateEvaluationResult } from '../evaluationSchema.js';

/** generic prompt used for all tests */
const prompt = "Please give me a causal loop diagram that captures the key variables and causal processes described in the background information.";
/** generic problem statement used for all tests */
const problemStatement = "I'm trying to understand the key variables and causal mechanisms that drive this system's behavior.";


/**
 * Generates a test case with expert knowledge and expected variable groups
 * @param {string} name Test name
 * @param {string} backgroundKnowledge Expert description of the system
 * @param {Array} expectedVariableGroups List of key variable groups that should be present in the CLD
 * @returns {Object} Test case with prompt, parameters, and expectations
 */
const generateTest = function(name, backgroundKnowledge, expectedVariableGroups) {
    return {
        name: name,
        prompt: prompt,
        additionalParameters: {
            problemStatement: problemStatement,
            backgroundKnowledge: backgroundKnowledge
        },
        expectations: {
            expectedVariableGroups: expectedVariableGroups
        }
    };
};

/**
 * How many links a required causal influence may travel through.
 *
 * The expert knowledge these tests supply describes influence in chains \u2014 "disease
 * transmission drives infection rates, which create pressure for policy interventions" \u2014 and
 * a modeller who writes that chain out has represented the influence the expectation asks
 * for. Demanding a single edge instead marked those models wrong, and every engine failed
 * the COVID test on edges the background never claimed were direct.
 *
 * Bounded, because in a dense CLD an unbounded search finds a path between almost any two
 * variables and the requirement would stop meaning anything. Three links covers the chains
 * the background prose actually describes.
 */
const MAX_CAUSAL_PATH_LENGTH = 3;

/**
 * Index a generated CLD as a signed directed graph over its declared variables.
 *
 * Endpoints are resolved to variables rather than used as written, keeping the rule that a
 * relationship only counts when both its ends name something the model actually declares.
 * @param {Object} generatedModel The CLD generated by the LLM
 * @returns {Object} { names, adjacency } where adjacency maps a variable to {to, sign} edges
 */
const buildCausalGraph = function(generatedModel) {
    const names = (generatedModel.variables || []).map((v) => { return v.name });
    const adjacency = new Map();

    const variablesNamed = function(endpoint) {
        return names.filter((name) => { return utils.evalsVariableNameMatches(endpoint, name) });
    };

    for (const rel of (generatedModel.relationships || [])) {
        const sign = rel.polarity === '-' ? -1 : 1;
        for (const from of variablesNamed(rel.from)) {
            for (const to of variablesNamed(rel.to)) {
                if (!adjacency.has(from)) adjacency.set(from, []);
                adjacency.get(from).push({ to, sign });
            }
        }
    }

    return { names, adjacency };
};

/**
 * Whether the model carries the required causal influence, directly or through a chain.
 *
 * A path's polarity is the product of its links, which is what makes an indirect route
 * comparable to the direct one the expectation names: two negative links compose to a
 * positive influence, and a modeller who wrote them has said the same thing.
 * @param {Object} graph The indexed model from buildCausalGraph
 * @param {Object} reqRel Required relationship {from, to, polarity}
 * @returns {boolean} True when a path of the required net polarity exists
 */
const requiredRelationshipIsPresent = function(graph, reqRel) {
    const sources = graph.names.filter((name) => { return utils.evalsVariableNameMatches(name, reqRel.from) });
    const targets = new Set(graph.names.filter((name) => { return utils.evalsVariableNameMatches(name, reqRel.to) }));
    if (sources.length === 0 || targets.size === 0)
        return false;

    const wantedSign = reqRel.polarity === '-' ? -1 : 1;
    // Visited is keyed by variable AND accumulated sign: reaching a variable positively says
    // nothing about whether it can also be reached negatively, and only one of those may be
    // the influence being asked for.
    const visited = new Set();
    let frontier = sources.map((name) => { return { node: name, sign: 1, links: 0 } });

    while (frontier.length > 0) {
        const next = [];
        for (const { node, sign, links } of frontier) {
            for (const edge of (graph.adjacency.get(node) || [])) {
                const nextSign = sign * edge.sign;
                if (targets.has(edge.to) && (!reqRel.polarity || nextSign === wantedSign))
                    return true;
                if (links + 1 >= MAX_CAUSAL_PATH_LENGTH)
                    continue;
                const key = edge.to + '\u0000' + nextSign;
                if (visited.has(key))
                    continue;
                visited.add(key);
                next.push({ node: edge.to, sign: nextSign, links: links + 1 });
            }
        }
        frontier = next;
    }

    return false;
};

/**
 * Checks if a variable group is represented in the generated CLD
 * @param {Object} variableGroup Expected variable group definition
 * @param {Object} generatedModel The CLD generated by the LLM
 * @param {Object} graph The indexed model from buildCausalGraph
 * @returns {boolean} True if the variable group is adequately represented
 */
const variableGroupIsPresent = function(variableGroup, generatedModel, graph) {
    const variables = generatedModel.variables || [];

    // Check if required variables are present (require 100% match)
    if (variableGroup.requiredVariables) {
        for (const variableName of variableGroup.requiredVariables) {
            const variable = variables.find(v => 
                utils.evalsVariableNameMatches(v.name, variableName)
            );
            if (!variable) {
                return false;
            }
        }
    }
    
    // Check if required relationships are present (focus on key causal patterns)
    if (variableGroup.requiredRelationships) {
        for (const reqRel of variableGroup.requiredRelationships) {
            if (!requiredRelationshipIsPresent(graph, reqRel)) {
                return false;
            }
        }
    }

    
    return true;
};

/**
 * This method compares the generated response to the ground truth and returns a list of failure objects
 * @param {Object} generatedResponse The response from the engine
 * @param {Object} expectations The expected variable groups and concepts information
 * @returns {Array<Object>} A list of failures with type and details.
 */
export const evaluate = function(generatedResponse, expectations) {
    const generatedModel = generatedResponse?.model || {};
    const expectedVariableGroups = expectations.expectedVariableGroups || [];
    const failures = [];

    // Check if the model has basic CLD structure
    const variables = generatedModel.variables || [];
    const relationships = generatedModel.relationships || [];
    
    if (variables.length === 0) {
        failures.push({
            type: "No variables found",
            details: "A causal loop diagram should contain at least one variable"
        });
    }
    
    if (relationships.length === 0) {
        failures.push({
            type: "No causal relationships found", 
            details: "A causal loop diagram should contain at least one causal relationship"
        });
    }

    const graph = buildCausalGraph(generatedModel);

    // Check each expected variable group
    for (const variableGroup of expectedVariableGroups) {
        if (!variableGroupIsPresent(variableGroup, generatedModel, graph)) {
            const missingElements = [];
            
            // Identify what's missing
            if (variableGroup.requiredVariables) {
                const missingVariables = variableGroup.requiredVariables.filter(variableName => 
                    !variables.some(v => utils.evalsVariableNameMatches(v.name, variableName))
                );
                if (missingVariables.length > 0) {
                    missingElements.push(`variables: ${missingVariables.join(', ')}`);
                }
            }
            
            if (variableGroup.requiredRelationships) {
                const missingRelationships = variableGroup.requiredRelationships.filter(reqRel => {
                    return !requiredRelationshipIsPresent(graph, reqRel);
                });
                if (missingRelationships.length > 0) {
                    const relationshipStrings = missingRelationships.map(rel => 
                        `${rel.from} → ${rel.to}${rel.polarity ? ` (${rel.polarity})` : ''}`
                    );
                    missingElements.push(`relationships: ${relationshipStrings.join(', ')}`);
                }
            }

            // If no specific missing elements identified, report that variable group requirements are not satisfied
            if (missingElements.length === 0) {
                missingElements.push(`variable group requirements not satisfied (unable to identify specific missing elements)`);
            }

            failures.push({
                type: "Missing key variable group",
                details: `Variable group "${variableGroup.name}" is not adequately represented. Missing: ${missingElements.join('; ')}`
            });
        }
    }

    return validateEvaluationResult(failures);
};

/**
 * Returns the description for this category
 * @returns {string} The description describing this category
 */
export const description = () => {
    return `The qualitative causal reasoning test evaluates whether causal loop diagrams (CLDs) generated by LLMs 
include key variables and causal mechanisms that domain experts consider essential for understanding particular systems, 
assessing the substantive quality of qualitative causal reasoning by comparing generated models against expert-identified 
variable groups and relationships across domains like public health and organizational change.`;
};

/**
 * Returns the methodology for this category: how its tests are built and run, what the evaluator
 * checks, and how those checks combine into a verdict. Each `criteria[].name` is the exact failure
 * `type` {@link evaluate} records when that criterion is not met. Rendered by the documentation
 * site on every test page.
 * @returns {{howItWorks: Array<string>, criteria: Array<{name: string, description: string}>, scoring: string}}
 */
export const methodology = () => ({
    howItWorks: [
        `Where causal translation asks whether an engine can transcribe relationships it is handed, this category asks whether the diagram it builds is substantively right about a real system. Each test supplies expert knowledge about a domain — COVID-19 pandemic response, a mental health crisis, digital transformation in an organization — and asks for a causal loop diagram capturing the key variables and causal processes in it. Real domains are used deliberately: the question is whether the diagram carries the conceptual elements that make it useful for policy analysis and systems thinking.`,
        `Expectations are expressed as variable groups, each naming the variables that must be present and the causal influences that must connect them, with polarity. A group is a coherent piece of the system's story, so failing one says which part of the domain the diagram missed rather than just that something was absent.`,
        `Variable names are matched flexibly: names are lower-cased with spaces, underscores and hyphens removed, and either name may contain the other, so "Infection Rate", "infection_rate" and "daily infection rate" all satisfy an expectation for "infection rate".`,
        `Required influences are checked against the diagram read as a signed directed graph, and are satisfied by a chain of up to three links, not only a single edge. A path's polarity is the product of its links, so two negative links compose to a positive influence. The expert prose describes influence in chains — transmission drives infections, which create pressure for interventions — and a modeler who writes that chain out has represented the influence being asked for; the bound is what keeps the requirement meaningful, since in a dense diagram an unbounded search connects almost any two variables. Relationship endpoints must also resolve to variables the model actually declares.`
    ],
    criteria: [
        { name: 'No variables found', description: 'The response contains no variables — not a causal loop diagram at all.' },
        { name: 'No causal relationships found', description: 'The response declares variables but no causal relationships between them.' },
        { name: 'Missing key variable group', description: 'A group of expert-identified elements is not adequately represented. Recorded once per group, naming exactly which required variables and which required influences (with polarity) were missing.' }
    ],
    scoring: `Every expected variable group must be fully represented: one missing variable or one missing influence within a group fails that group, and one failed group fails the test. Additional variables and relationships beyond the expectations are not penalized — the diagram may be richer than the ground truth, it just may not be missing any of it.`
});

